import re
from pathlib import Path

SEP = r'[\s\-()]*'
TAIL = rf'(?:{SEP}\d){{9}}'
P_INTL = rf'\+?{SEP}3{SEP}8{SEP}0{TAIL}'
P_LOCAL = rf'\(?0{TAIL}'
NUMBER_RE = re.compile(rf'(?<!\d)(?:{P_INTL}|{P_LOCAL})(?!\d)')


def main():
    text = Path('дані', 'контакти.txt').read_text(encoding='utf-8')
    found = set()
    for m in NUMBER_RE.finditer(text):
        digits = re.sub(r'\D', '', m.group())
        if len(digits) == 12 and digits.startswith('380'):
            found.add('+' + digits)
        elif len(digits) == 10 and digits.startswith('0'):
            found.add('+38' + digits)
    for number in sorted(found):
        print(number)


if __name__ == '__main__':
    main()
